dashboard.definition:
{
  "title": "Revue des comptes AD (SecOps)",
  "description": "Revue périodique des comptes Active Directory par les équipes SecOps : chaque compte reçoit un score de risque et les raisons pour lesquelles il doit être revu (privilégié, mot de passe sans expiration, inactif, expiré, SPN avec ancien mot de passe, délégation, désactivé mais encore privilégié...), ainsi que son statut de revue et ses informations de responsable. Filtrez par OU, périmètre, statut de revue et risque, exportez la liste pour les responsables de comptes et consignez les décisions dans adx_review_decisions.csv. Basé sur les lookups AD Objects (dernier rafraîchissement, pas du LDAP en direct).",
  "inputs": {
    "input_ou": {
      "type": "input.text",
      "title": "Filtre OU (regex)",
      "options": {
        "token": "ou_f",
        "defaultValue": ".*"
      }
    },
    "input_scope": {
      "type": "input.dropdown",
      "title": "Périmètre",
      "options": {
        "token": "scope",
        "defaultValue": "1=1",
        "items": [
          {
            "label": "Tous les comptes",
            "value": "1=1"
          },
          {
            "label": "Comptes actifs uniquement",
            "value": "is_disabled=0"
          },
          {
            "label": "Comptes privilégiés",
            "value": "is_privileged=1"
          },
          {
            "label": "Comptes de service (SPN)",
            "value": "isnotnull(servicePrincipalName)"
          },
          {
            "label": "Mot de passe sans expiration",
            "value": "pwd_never_expires=1"
          },
          {
            "label": "Comptes désactivés",
            "value": "is_disabled=1"
          }
        ]
      }
    },
    "input_rstatus": {
      "type": "input.dropdown",
      "title": "Statut de revue",
      "options": {
        "token": "rstatus",
        "defaultValue": "1=1",
        "items": [
          {
            "label": "Tous",
            "value": "1=1"
          },
          {
            "label": "À revoir (jamais / partielle / en retard)",
            "value": "(review_status=\"Jamais revu\" OR review_status=\"Revue partielle\" OR review_status=\"Revue en retard\")"
          },
          {
            "label": "Jamais revus",
            "value": "review_status=\"Jamais revu\""
          },
          {
            "label": "Revue partielle",
            "value": "review_status=\"Revue partielle\""
          },
          {
            "label": "Revue en retard",
            "value": "review_status=\"Revue en retard\""
          },
          {
            "label": "Conformes (rien à revoir)",
            "value": "review_status=\"Conforme\""
          },
          {
            "label": "Revus",
            "value": "review_status=\"Revu\""
          }
        ]
      }
    },
    "input_min": {
      "type": "input.dropdown",
      "title": "Risque minimum",
      "options": {
        "token": "min_risk",
        "defaultValue": "1",
        "items": [
          {
            "label": "Tous (score >= 0)",
            "value": "0"
          },
          {
            "label": "FAIBLE et plus",
            "value": "1"
          },
          {
            "label": "MOYEN et plus",
            "value": "3"
          },
          {
            "label": "ÉLEVÉ uniquement",
            "value": "6"
          }
        ]
      }
    }
  },
  "defaults": {},
  "visualizations": {
    "viz_1": {
      "type": "splunk.singlevalue",
      "title": "Comptes dans le périmètre",
      "dataSources": {
        "primary": "ds_1"
      },
      "options": {
        "sparklineDisplay": "off",
        "trendDisplay": "off"
      },
      "eventHandlers": [
        {
          "type": "drilldown.linkToSearch",
          "options": {
            "query": "| `adx_users` | where match(ou,\"(?i)$ou_f$\") `adx_risk` | where $scope$ AND $rstatus$ | eval etat=if(is_disabled=1,\"Désactivé\",\"Actif\"), pwd_set=strftime(pwd_last_set,\"%Y-%m-%d %H:%M\"), derniere_connexion=strftime(last_logon,\"%Y-%m-%d\"), cree_le=strftime(created,\"%Y-%m-%d\"), groupes=mvjoin(priv_groups,\", \"), raisons=mvjoin(review_reasons,\" | \"), restantes=mvjoin(remaining,\" | \") | table sam display_name upn etat risk_level risk_score raisons restantes review_progress department description location ou pwd_set pwd_age_days derniere_connexion cree_le groupes review_status decision reviewer review_date comment | rename sam as \"Compte\", display_name as \"Nom affiché\", upn as \"UPN\", etat as \"État\", risk_level as \"Niveau de risque\", risk_score as \"Score\", raisons as \"Raisons de la revue\", restantes as \"Raisons restantes à traiter\", review_progress as \"Avancement de la revue\", department as \"Service\", description as \"Description\", location as \"Localisation\", ou as \"OU\", pwd_set as \"Mot de passe changé le\", pwd_age_days as \"Âge du mot de passe (j)\", derniere_connexion as \"Dernière connexion\", cree_le as \"Créé le\", groupes as \"Groupes privilégiés\", review_status as \"Statut de revue\", decision as \"Décision\", reviewer as \"Relecteur\", review_date as \"Date de revue\", comment as \"Commentaire\"",
            "earliest": "-24h",
            "latest": "now",
            "type": "custom",
            "newTab": true
          }
        }
      ]
    },
    "viz_2": {
      "type": "splunk.singlevalue",
      "title": "Risque ÉLEVÉ",
      "dataSources": {
        "primary": "ds_2"
      },
      "options": {
        "sparklineDisplay": "off",
        "trendDisplay": "off",
        "majorColor": "> majorValue | rangeValue(majorColorEditorConfig)"
      },
      "context": {
        "majorColorEditorConfig": [
          {
            "value": "#65A637",
            "to": 1
          },
          {
            "value": "#B0413E",
            "from": 1
          }
        ]
      },
      "eventHandlers": [
        {
          "type": "drilldown.linkToSearch",
          "options": {
            "query": "| `adx_users` | where match(ou,\"(?i)$ou_f$\") `adx_risk` | where $scope$ AND $rstatus$ | where risk_level=\"ÉLEVÉ\" | eval etat=if(is_disabled=1,\"Désactivé\",\"Actif\"), pwd_set=strftime(pwd_last_set,\"%Y-%m-%d %H:%M\"), derniere_connexion=strftime(last_logon,\"%Y-%m-%d\"), cree_le=strftime(created,\"%Y-%m-%d\"), groupes=mvjoin(priv_groups,\", \"), raisons=mvjoin(review_reasons,\" | \"), restantes=mvjoin(remaining,\" | \") | table sam display_name upn etat risk_level risk_score raisons restantes review_progress department description location ou pwd_set pwd_age_days derniere_connexion cree_le groupes review_status decision reviewer review_date comment | rename sam as \"Compte\", display_name as \"Nom affiché\", upn as \"UPN\", etat as \"État\", risk_level as \"Niveau de risque\", risk_score as \"Score\", raisons as \"Raisons de la revue\", restantes as \"Raisons restantes à traiter\", review_progress as \"Avancement de la revue\", department as \"Service\", description as \"Description\", location as \"Localisation\", ou as \"OU\", pwd_set as \"Mot de passe changé le\", pwd_age_days as \"Âge du mot de passe (j)\", derniere_connexion as \"Dernière connexion\", cree_le as \"Créé le\", groupes as \"Groupes privilégiés\", review_status as \"Statut de revue\", decision as \"Décision\", reviewer as \"Relecteur\", review_date as \"Date de revue\", comment as \"Commentaire\"",
            "earliest": "-24h",
            "latest": "now",
            "type": "custom",
            "newTab": true
          }
        }
      ]
    },
    "viz_3": {
      "type": "splunk.singlevalue",
      "title": "Risque MOYEN",
      "dataSources": {
        "primary": "ds_3"
      },
      "options": {
        "sparklineDisplay": "off",
        "trendDisplay": "off",
        "majorColor": "> majorValue | rangeValue(majorColorEditorConfig)"
      },
      "context": {
        "majorColorEditorConfig": [
          {
            "value": "#65A637",
            "to": 1
          },
          {
            "value": "#F1813F",
            "from": 1
          }
        ]
      },
      "eventHandlers": [
        {
          "type": "drilldown.linkToSearch",
          "options": {
            "query": "| `adx_users` | where match(ou,\"(?i)$ou_f$\") `adx_risk` | where $scope$ AND $rstatus$ | where risk_level=\"MOYEN\" | eval etat=if(is_disabled=1,\"Désactivé\",\"Actif\"), pwd_set=strftime(pwd_last_set,\"%Y-%m-%d %H:%M\"), derniere_connexion=strftime(last_logon,\"%Y-%m-%d\"), cree_le=strftime(created,\"%Y-%m-%d\"), groupes=mvjoin(priv_groups,\", \"), raisons=mvjoin(review_reasons,\" | \"), restantes=mvjoin(remaining,\" | \") | table sam display_name upn etat risk_level risk_score raisons restantes review_progress department description location ou pwd_set pwd_age_days derniere_connexion cree_le groupes review_status decision reviewer review_date comment | rename sam as \"Compte\", display_name as \"Nom affiché\", upn as \"UPN\", etat as \"État\", risk_level as \"Niveau de risque\", risk_score as \"Score\", raisons as \"Raisons de la revue\", restantes as \"Raisons restantes à traiter\", review_progress as \"Avancement de la revue\", department as \"Service\", description as \"Description\", location as \"Localisation\", ou as \"OU\", pwd_set as \"Mot de passe changé le\", pwd_age_days as \"Âge du mot de passe (j)\", derniere_connexion as \"Dernière connexion\", cree_le as \"Créé le\", groupes as \"Groupes privilégiés\", review_status as \"Statut de revue\", decision as \"Décision\", reviewer as \"Relecteur\", review_date as \"Date de revue\", comment as \"Commentaire\"",
            "earliest": "-24h",
            "latest": "now",
            "type": "custom",
            "newTab": true
          }
        }
      ]
    },
    "viz_4": {
      "type": "splunk.singlevalue",
      "title": "Jamais revus (comptes actifs)",
      "dataSources": {
        "primary": "ds_4"
      },
      "options": {
        "sparklineDisplay": "off",
        "trendDisplay": "off",
        "majorColor": "> majorValue | rangeValue(majorColorEditorConfig)"
      },
      "context": {
        "majorColorEditorConfig": [
          {
            "value": "#65A637",
            "to": 1
          },
          {
            "value": "#FFC300",
            "from": 1
          }
        ]
      },
      "eventHandlers": [
        {
          "type": "drilldown.linkToSearch",
          "options": {
            "query": "| `adx_users` | where match(ou,\"(?i)$ou_f$\") `adx_risk` | where $scope$ AND $rstatus$ | where review_status=\"Jamais revu\" AND is_disabled=0 | eval etat=if(is_disabled=1,\"Désactivé\",\"Actif\"), pwd_set=strftime(pwd_last_set,\"%Y-%m-%d %H:%M\"), derniere_connexion=strftime(last_logon,\"%Y-%m-%d\"), cree_le=strftime(created,\"%Y-%m-%d\"), groupes=mvjoin(priv_groups,\", \"), raisons=mvjoin(review_reasons,\" | \"), restantes=mvjoin(remaining,\" | \") | table sam display_name upn etat risk_level risk_score raisons restantes review_progress department description location ou pwd_set pwd_age_days derniere_connexion cree_le groupes review_status decision reviewer review_date comment | rename sam as \"Compte\", display_name as \"Nom affiché\", upn as \"UPN\", etat as \"État\", risk_level as \"Niveau de risque\", risk_score as \"Score\", raisons as \"Raisons de la revue\", restantes as \"Raisons restantes à traiter\", review_progress as \"Avancement de la revue\", department as \"Service\", description as \"Description\", location as \"Localisation\", ou as \"OU\", pwd_set as \"Mot de passe changé le\", pwd_age_days as \"Âge du mot de passe (j)\", derniere_connexion as \"Dernière connexion\", cree_le as \"Créé le\", groupes as \"Groupes privilégiés\", review_status as \"Statut de revue\", decision as \"Décision\", reviewer as \"Relecteur\", review_date as \"Date de revue\", comment as \"Commentaire\"",
            "earliest": "-24h",
            "latest": "now",
            "type": "custom",
            "newTab": true
          }
        }
      ]
    },
    "viz_5": {
      "type": "splunk.singlevalue",
      "title": "Revues partielles",
      "dataSources": {
        "primary": "ds_5"
      },
      "options": {
        "sparklineDisplay": "off",
        "trendDisplay": "off",
        "majorColor": "> majorValue | rangeValue(majorColorEditorConfig)"
      },
      "context": {
        "majorColorEditorConfig": [
          {
            "value": "#65A637",
            "to": 1
          },
          {
            "value": "#FFC300",
            "from": 1
          }
        ]
      },
      "eventHandlers": [
        {
          "type": "drilldown.linkToSearch",
          "options": {
            "query": "| `adx_users` | where match(ou,\"(?i)$ou_f$\") `adx_risk` | where $scope$ AND $rstatus$ | where review_status=\"Revue partielle\" | eval etat=if(is_disabled=1,\"Désactivé\",\"Actif\"), pwd_set=strftime(pwd_last_set,\"%Y-%m-%d %H:%M\"), derniere_connexion=strftime(last_logon,\"%Y-%m-%d\"), cree_le=strftime(created,\"%Y-%m-%d\"), groupes=mvjoin(priv_groups,\", \"), raisons=mvjoin(review_reasons,\" | \"), restantes=mvjoin(remaining,\" | \") | table sam display_name upn etat risk_level risk_score raisons restantes review_progress department description location ou pwd_set pwd_age_days derniere_connexion cree_le groupes review_status decision reviewer review_date comment | rename sam as \"Compte\", display_name as \"Nom affiché\", upn as \"UPN\", etat as \"État\", risk_level as \"Niveau de risque\", risk_score as \"Score\", raisons as \"Raisons de la revue\", restantes as \"Raisons restantes à traiter\", review_progress as \"Avancement de la revue\", department as \"Service\", description as \"Description\", location as \"Localisation\", ou as \"OU\", pwd_set as \"Mot de passe changé le\", pwd_age_days as \"Âge du mot de passe (j)\", derniere_connexion as \"Dernière connexion\", cree_le as \"Créé le\", groupes as \"Groupes privilégiés\", review_status as \"Statut de revue\", decision as \"Décision\", reviewer as \"Relecteur\", review_date as \"Date de revue\", comment as \"Commentaire\"",
            "earliest": "-24h",
            "latest": "now",
            "type": "custom",
            "newTab": true
          }
        }
      ]
    },
    "viz_6": {
      "type": "splunk.singlevalue",
      "title": "Revues en retard",
      "dataSources": {
        "primary": "ds_6"
      },
      "options": {
        "sparklineDisplay": "off",
        "trendDisplay": "off",
        "majorColor": "> majorValue | rangeValue(majorColorEditorConfig)"
      },
      "context": {
        "majorColorEditorConfig": [
          {
            "value": "#65A637",
            "to": 1
          },
          {
            "value": "#B0413E",
            "from": 1
          }
        ]
      },
      "eventHandlers": [
        {
          "type": "drilldown.linkToSearch",
          "options": {
            "query": "| `adx_users` | where match(ou,\"(?i)$ou_f$\") `adx_risk` | where $scope$ AND $rstatus$ | where review_status=\"Revue en retard\" | eval etat=if(is_disabled=1,\"Désactivé\",\"Actif\"), pwd_set=strftime(pwd_last_set,\"%Y-%m-%d %H:%M\"), derniere_connexion=strftime(last_logon,\"%Y-%m-%d\"), cree_le=strftime(created,\"%Y-%m-%d\"), groupes=mvjoin(priv_groups,\", \"), raisons=mvjoin(review_reasons,\" | \"), restantes=mvjoin(remaining,\" | \") | table sam display_name upn etat risk_level risk_score raisons restantes review_progress department description location ou pwd_set pwd_age_days derniere_connexion cree_le groupes review_status decision reviewer review_date comment | rename sam as \"Compte\", display_name as \"Nom affiché\", upn as \"UPN\", etat as \"État\", risk_level as \"Niveau de risque\", risk_score as \"Score\", raisons as \"Raisons de la revue\", restantes as \"Raisons restantes à traiter\", review_progress as \"Avancement de la revue\", department as \"Service\", description as \"Description\", location as \"Localisation\", ou as \"OU\", pwd_set as \"Mot de passe changé le\", pwd_age_days as \"Âge du mot de passe (j)\", derniere_connexion as \"Dernière connexion\", cree_le as \"Créé le\", groupes as \"Groupes privilégiés\", review_status as \"Statut de revue\", decision as \"Décision\", reviewer as \"Relecteur\", review_date as \"Date de revue\", comment as \"Commentaire\"",
            "earliest": "-24h",
            "latest": "now",
            "type": "custom",
            "newTab": true
          }
        }
      ]
    },
    "viz_7": {
      "type": "splunk.singlevalue",
      "title": "Désactivés à supprimer",
      "dataSources": {
        "primary": "ds_7"
      },
      "options": {
        "sparklineDisplay": "off",
        "trendDisplay": "off",
        "underLabel": "désactivés depuis longtemps ou encore privilégiés"
      },
      "eventHandlers": [
        {
          "type": "drilldown.linkToSearch",
          "options": {
            "query": "| `adx_users` | where match(ou,\"(?i)$ou_f$\") `adx_risk` | where $scope$ AND $rstatus$ | where is_disabled=1 AND risk_score>=1 | eval etat=if(is_disabled=1,\"Désactivé\",\"Actif\"), pwd_set=strftime(pwd_last_set,\"%Y-%m-%d %H:%M\"), derniere_connexion=strftime(last_logon,\"%Y-%m-%d\"), cree_le=strftime(created,\"%Y-%m-%d\"), groupes=mvjoin(priv_groups,\", \"), raisons=mvjoin(review_reasons,\" | \"), restantes=mvjoin(remaining,\" | \") | table sam display_name upn etat risk_level risk_score raisons restantes review_progress department description location ou pwd_set pwd_age_days derniere_connexion cree_le groupes review_status decision reviewer review_date comment | rename sam as \"Compte\", display_name as \"Nom affiché\", upn as \"UPN\", etat as \"État\", risk_level as \"Niveau de risque\", risk_score as \"Score\", raisons as \"Raisons de la revue\", restantes as \"Raisons restantes à traiter\", review_progress as \"Avancement de la revue\", department as \"Service\", description as \"Description\", location as \"Localisation\", ou as \"OU\", pwd_set as \"Mot de passe changé le\", pwd_age_days as \"Âge du mot de passe (j)\", derniere_connexion as \"Dernière connexion\", cree_le as \"Créé le\", groupes as \"Groupes privilégiés\", review_status as \"Statut de revue\", decision as \"Décision\", reviewer as \"Relecteur\", review_date as \"Date de revue\", comment as \"Commentaire\"",
            "earliest": "-24h",
            "latest": "now",
            "type": "custom",
            "newTab": true
          }
        }
      ]
    },
    "viz_8": {
      "type": "splunk.pie",
      "title": "Répartition par niveau de risque",
      "dataSources": {
        "primary": "ds_8"
      },
      "options": {
        "legendDisplay": "bottom"
      },
      "eventHandlers": [
        {
          "type": "drilldown.linkToSearch",
          "options": {
            "query": "| `adx_users` | where match(ou,\"(?i)$ou_f$\") `adx_risk` | where $scope$ AND $rstatus$ | stats count by risk_level",
            "earliest": "-24h",
            "latest": "now",
            "type": "custom",
            "newTab": true
          }
        }
      ]
    },
    "viz_9": {
      "type": "splunk.bar",
      "title": "Principales raisons de revue",
      "dataSources": {
        "primary": "ds_9"
      },
      "options": {
        "legendDisplay": "off"
      },
      "eventHandlers": [
        {
          "type": "drilldown.linkToSearch",
          "options": {
            "query": "| `adx_users` | where match(ou,\"(?i)$ou_f$\") `adx_risk` | where $scope$ AND $rstatus$ | mvexpand review_reasons | stats count by review_reasons | sort - count | head 12",
            "earliest": "-24h",
            "latest": "now",
            "type": "custom",
            "newTab": true
          }
        }
      ]
    },
    "viz_10": {
      "type": "splunk.pie",
      "title": "Statut des revues",
      "dataSources": {
        "primary": "ds_10"
      },
      "options": {
        "legendDisplay": "bottom"
      },
      "eventHandlers": [
        {
          "type": "drilldown.linkToSearch",
          "options": {
            "query": "| `adx_users` | where match(ou,\"(?i)$ou_f$\") `adx_risk` | where $scope$ AND $rstatus$ | stats count by review_status",
            "earliest": "-24h",
            "latest": "now",
            "type": "custom",
            "newTab": true
          }
        }
      ]
    },
    "viz_11": {
      "type": "splunk.table",
      "title": "Comptes à revoir",
      "dataSources": {
        "primary": "ds_11"
      },
      "options": {
        "count": 15,
        "wrap": true,
        "columnFormat": {
          "Niveau de risque": {
            "rowBackgroundColors": "> table | seriesByName(\"Niveau de risque\") | matchValue(col0ColorConfig)"
          },
          "Statut de revue": {
            "rowBackgroundColors": "> table | seriesByName(\"Statut de revue\") | matchValue(col1ColorConfig)"
          }
        }
      },
      "description": "Trié par score de risque. Utilisez les filtres ci-dessus (OU, périmètre, statut de revue, risque minimum). Exportez avec « Ouvrir dans la recherche » puis Exporter en CSV pour transmettre la liste aux responsables de comptes ; consignez le résultat dans lookups/adx_review_decisions.csv (sam, decision, reviewer, review_date AAAA-MM-JJ, comment).",
      "context": {
        "col0ColorConfig": [
          {
            "match": "ÉLEVÉ",
            "value": "#B0413E"
          },
          {
            "match": "MOYEN",
            "value": "#F1813F"
          },
          {
            "match": "FAIBLE",
            "value": "#F8BE34"
          },
          {
            "match": "OK",
            "value": "#65A637"
          }
        ],
        "col1ColorConfig": [
          {
            "match": "Jamais revu",
            "value": "#B0413E"
          },
          {
            "match": "Revue en retard",
            "value": "#F1813F"
          },
          {
            "match": "Revue partielle",
            "value": "#F8BE34"
          },
          {
            "match": "Revu",
            "value": "#65A637"
          },
          {
            "match": "Conforme",
            "value": "#65A637"
          }
        ]
      },
      "eventHandlers": [
        {
          "type": "drilldown.linkToSearch",
          "options": {
            "query": "| `adx_users` `adx_risk` | where sam=\"$row.Compte.value$\" | eval etat=if(is_disabled=1,\"Désactivé\",\"Actif\"), pwd_set=strftime(pwd_last_set,\"%Y-%m-%d %H:%M\"), derniere_connexion=strftime(last_logon,\"%Y-%m-%d\"), cree_le=strftime(created,\"%Y-%m-%d\"), groupes=mvjoin(priv_groups,\", \"), raisons=mvjoin(review_reasons,\" | \"), restantes=mvjoin(remaining,\" | \") | table sam display_name upn etat risk_level risk_score raisons restantes review_progress department description location ou pwd_set pwd_age_days derniere_connexion cree_le groupes review_status decision reviewer review_date comment | rename sam as \"Compte\", display_name as \"Nom affiché\", upn as \"UPN\", etat as \"État\", risk_level as \"Niveau de risque\", risk_score as \"Score\", raisons as \"Raisons de la revue\", restantes as \"Raisons restantes à traiter\", review_progress as \"Avancement de la revue\", department as \"Service\", description as \"Description\", location as \"Localisation\", ou as \"OU\", pwd_set as \"Mot de passe changé le\", pwd_age_days as \"Âge du mot de passe (j)\", derniere_connexion as \"Dernière connexion\", cree_le as \"Créé le\", groupes as \"Groupes privilégiés\", review_status as \"Statut de revue\", decision as \"Décision\", reviewer as \"Relecteur\", review_date as \"Date de revue\", comment as \"Commentaire\"",
            "earliest": "-24h",
            "latest": "now",
            "type": "custom",
            "newTab": true
          }
        }
      ]
    },
    "viz_12": {
      "type": "splunk.table",
      "title": "Charge de revue par service (department)",
