        "count": 8,
        "wrap": true
      },
      "eventHandlers": [
        {
          "type": "drilldown.linkToSearch",
          "options": {
            "query": "| `adx_users` | where match(ou,\"(?i)$ou_f$\") `adx_risk` | where $scope$ AND $rstatus$ | eval owner=coalesce(mvindex(department,0),\"(non renseigné)\") | stats count as accounts, sum(eval(if(risk_level=\"ÉLEVÉ\",1,0))) as high, sum(eval(if(review_status=\"Conforme\" OR review_status=\"Revu\",0,1))) as to_review by owner | sort - high, - to_review | rename owner as \"Service\", accounts as \"Comptes\", high as \"Risque élevé\", to_review as \"À revoir\"",
